import React from "react";


export default function ErrorList({ errors }) {
  if (!errors || errors.length === 0 || (errors.length === 1 && !errors[0].line)) {
    return <p className="no-error">✅ No errors found!</p>;
  }

  return (
    <div className="error-list">
      {errors.map(
        (err, index) =>
          err.line && (
            <div key={index} className={`error-item ${err.type.toLowerCase()}`}>
              <strong>{err.type} Error</strong> (line {err.line}): {err.message}
            </div>
          )
      )}
    </div>
  );
}
